Here's a complete example of data-driven MSTest tests for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- DataRow: inline test cases for CalculateTotal ---
    [TestMethod]
    [DataRow(1, 10.00, 10.00)]
    [DataRow(5, 3.50, 17.50)]
    [DataRow(0, 99.99, 0.00)]
    [DataRow(100, 0.01, 1.00)]
    public void CalculateTotal_ReturnsExpected(int quantity, double unitPrice, double expected)
    {
        var result = _calculator.CalculateTotal(quantity, (decimal)unitPrice);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DataRow: edge/error cases ---
    [TestMethod]
    [DataRow(-1, 10.00)]
    [DataRow(1, -5.00)]
    public void CalculateTotal_InvalidInputs_Throws(int quantity, double unitPrice)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(quantity, (decimal)unitPrice));
    }

    // --- DynamicData from method: ApplyDiscount scenarios ---
    [TestMethod]
    [DynamicData(nameof(GetDiscountTestCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_ReturnsExpected(decimal total, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(total, discountPercent);
        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<object[]> GetDiscountTestCases()
    {
        yield return new object[] { 100m, 0m, 100m };      // no discount
        yield return new object[] { 100m, 10m, 90m };      // 10% off
        yield return new object[] { 200m, 50m, 100m };     // half off
        yield return new object[] { 49.99m, 25m, 37.4925m }; // fractional
        yield return new object[] { 0m, 15m, 0m };         // zero total
    }

    // --- DynamicData from property ---
    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases), DynamicDataSourceType.Property)]
    public void ApplyDiscount_InvalidDiscount_Throws(decimal total, decimal discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(total, discountPercent));
    }

    public static IEnumerable<object[]> InvalidDiscountCases => new[]
    {
        new object[] { 100m, -5m },   // negative discount
        new object[] { 100m, 101m },  // over 100%
        new object[] { -10m, 10m },   // negative total
    };
}
```

**Key points:**

| Technique | Best for |
|-----------|----------|
| `[DataRow]` | Simple inline values (compile-time constants only) |
| `[DynamicData]` with method | Complex types, `decimal` literals, computed cases |
| `[DynamicData]` with property | Same as method, but when data is static/reusable |

**Modern MSTest best practices used:**
- `[TestInitialize]` for shared setup
- Separate tests for happy-path vs. error cases
- Descriptive method names: `Method_Scenario_Expected`
- `DataRow` uses `double` (constant requirement) then casts; `DynamicData` uses `decimal` directly for precision
- `ThrowsException<T>` for validation tests

Adapt the method signatures and expected values to match your actual `PriceCalculator` implementation.
